  ["quest:sandoria:103"] = {
    objective_name = "Escort for Hire (San d'Oria)",
    page = {
      title = "Escort for Hire (San d'Oria)",
      page_id = 9249,
      revision_id = 1743859,
      revision_timestamp = "2021-07-01T21:01:33Z",
      content_sha256 = "b2e8f615c709bf1bf18d597c73b71be5fc3ef978a518396f894f3474178c417e",
      source_url = "https://ffxiclopedia.fandom.com/wiki/Escort_for_Hire_(San_d'Oria)",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "Talk to Rondipur in Northern San d'Oria to activate the quest.",
        action = "talk",
        entities = { "Rondipur", "Northern San d'Oria" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "Zone into The Eldieme Necropolis from Batallia Downs I-10 (Entrance 1). The fastest way there is using the survival guide located just inside. If you use this, you must zone out and back in to activate the quest.",
        action = "use",
        entities = { "The Eldieme Necropolis" },
        zones = { "Batallia Downs" },
        map_numbers = {  },
        grid_coordinates = { "I-10" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "The first person to zone into the dungeon will get a cut scene with Cannau about the quest.",
        action = "travel",
        entities = { "Cannau" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "*",
        depth = 1,
        instruction = "That person must talk to Cannau to start the quest. You will have 30 minutes to finish from this point. If noone talks to her, after several minutes she will leave.",
        action = "talk",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 5,
        marker = "*",
        depth = 1,
        instruction = "After talking to Cannau, she will immediately bolt away and start towards her destination with no thought for aggro at all. Anyone can stop and start her, simply talk to her; she will reply \"Why have we stopped?.\" This way you can safely fight mobs with her out of aggro and AoE range. To start her moving again, talk to her once more.",
        action = "talk",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 6,
        marker = "**",
        depth = 2,
        instruction = "Make sure you give the order to stop well in advance of where you actually want her to stop...due to lag she will sometimes take a few steps before she responds, and thus aggro unintentionally.",
        action = "trade",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 7,
        marker = "*",
        depth = 1,
        instruction = "If Cannau's HP gets low (in the yellow) she will draw hate from the undead at a distance; Cannau can be cured.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 8,
        marker = "*",
        depth = 1,
        instruction = "She will wind her way to the switch at (H-8) to open the doors.",
        action = "use",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "H-8" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 9,
        marker = "*",
        depth = 1,
        instruction = "After throwing the switch, she will go one of the two ways that you can continue on to the west (the ultimate goal is the room at (F-8).",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "F-8" },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 10,
        marker = "*",
        depth = 1,
        instruction = "Once she gets to the eastern or western wall of the room at (F-8), she will stop. Talking to her will get you a key item Completion Certificate. You have about 20 seconds to talk to the escortee before she warps out.",
        action = "talk",
        entities = { "Completion Certificate" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = { "F-8" },
        items = {  },
        key_items = { "Completion Certificate (Key Item)" },
        warnings = {  },
      },
      {
        order = 11,
        marker = "*",
        depth = 1,
        instruction = "Go back to Rondipur in Northern San d'Oria to receive your Page from Miratete's Memoirs and 10,000g if it's your first completion.",
        action = "obtain",
        entities = { "Rondipur", "Page from Miratete's Memoirs" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 12,
        marker = "*",
        depth = 1,
        instruction = "Notes:",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 13,
        marker = "*",
        depth = 1,
        instruction = "06/09/2008 Update",
        action = "note",
        entities = { "06/09/2008 Update" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 14,
        marker = "**",
        depth = 2,
        instruction = "Any of the three Escort for Hire quests may now be undertaken simultaneously with the quests All by Myself and The Big One.",
        action = "note",
        entities = { "Escort for Hire", "All by Myself", "The Big One" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 15,
        marker = "*",
        depth = 1,
        instruction = "Only one Escort for Hire quest can be active at any time. Only one Escort for Hire quest can be completed per Conquest Tally. In other words, if you finish Escort for Hire (San d'Oria), you cannot do another Escort for Hire quest until the next Conquest Tally.",
        action = "note",
        entities = { "Escort for Hire", "Escort for Hire (San d'Oria)" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 16,
        marker = "*",
        depth = 1,
        instruction = "Any of the escort quests can be easily deactivated by talking to the same person who gave you the quest.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 17,
        marker = "*",
        depth = 1,
        instruction = "Do not talk to the escortee until everyone who is in the party is in the dungeon. Anyone not in the zone when you begin the quest (i.e., still zoning) will not get credit for the quest.",
        action = "talk",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 18,
        marker = "*",
        depth = 1,
        instruction = "Although you can go in with an alliance, only the people in the starting person's party will get credit for the quest at the end. If you want to do this for more than 6 people, you will have to do it multiple times.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 19,
        marker = "*",
        depth = 1,
        instruction = "If the escortee dies, you only have to zone out and zone back in to restart the quest.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 20,
        marker = "*",
        depth = 1,
        instruction = "You will receive both the 10k gil and the key item Completion Certificate the first time you complete this quest. Each time you complete this quest after the first time, you will only receive the certificate.",
        action = "obtain",
        entities = { "Completion Certificate" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = { "Completion Certificate (Key Item)" },
        warnings = {  },
      },
      {
        order = 21,
        marker = "*",
        depth = 1,
        instruction = "You cannot sneak or invisible the escortee.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 22,
        marker = "*",
        depth = 1,
        instruction = "The escortee can go through the gates even when they are down. If another party is in the Necropolis and is throwing the switches, you may want to leave a member of your group posted at the switches until after you clear the gates.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 23,
        marker = "*",
        depth = 1,
        instruction = "The player who receives the cutscene upon zoning into Eldieme Necropolis will be unable to call their Adventuring Fellow NPC during the escort quest. However, other members of the party will be able to do so. Alter Egos may be summoned.",
        action = "note",
        entities = { "Adventuring Fellow", "Alter Egos" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 24,
        marker = "*",
        depth = 1,
        instruction = "If doing this with multiple people, designate one person to be the one that will control the NPC...it makes things easier and prevents issues with stopping/starting her.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
