  ["quest:sandoria:104"] = {
    objective_name = "A Discerning Eye",
    page = {
      title = "A Discerning Eye",
      page_id = 2797,
      revision_id = 1739355,
      revision_timestamp = "2021-04-23T13:35:13Z",
      content_sha256 = "caa727ef33df8e8124bb91fcfe836d7d067caaeaddef733b21f9358adb6c426a",
      source_url = "https://ffxiclopedia.fandom.com/wiki/A_Discerning_Eye",
      license = "CC-BY-SA-3.0",
    },
    steps = {
      {
        order = 1,
        marker = "*",
        depth = 1,
        instruction = "The quest will show up under the quests of the city you started it in and fame will be assigned to that city.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 2,
        marker = "*",
        depth = 1,
        instruction = "The starting NPC informs you that he/she found a lost package and asks you to return it to the owner, who is a passenger on the next airship.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 3,
        marker = "*",
        depth = 1,
        instruction = "If you accept the assignment, you will be shown the owner of the package.",
        action = "note",
        entities = {  },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
      },
      {
        order = 4,
        marker = "*",
        depth = 1,
        instruction = "The 'owner' is a randomly generated NPC, including Race, face/hair, and clothing. You will be allowed to repeat the viewing until you say \"I got it\". At this point you receive the key item Dropped Item.",
        action = "obtain",
        entities = { "Race", "Dropped Item" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = { "Dropped Item" },
        warnings = {  },
      },
      {
        order = 5,
        marker = "*",
        depth = 1,
        instruction = "Once airborne you have until you land to find the true owner. There will be 8 Passengers on this ship which look similar to the owner. The variations are always in the clothing and hair, and not the race/gender/face. Sometimes the Passengers are in hard-to-see places, such as the top of the canopy over the stairs from below deck, or behind covered section of the propeller engine.",
        action = "note",
        entities = { "Passenger" },
        zones = {  },
        map_numbers = {  },
        grid_coordinates = {  },
        items = {  },
        key_items = {  },
        warnings = {  },
